from rules import resolve


def solve(data):
    return resolve(data)

def _bounds(value):
    if value is None:
        return (None, None)
    if isinstance(value, dict):
        if "range" in value:
            return _bounds(value["range"])
        low = value.get("min", value.get("minimum", value.get("min_version")))
        high = value.get("max", value.get("maximum", value.get("max_version")))
        return (low, high)
    if isinstance(value, (list, tuple)):
        if len(value) == 2:
            return (value[0], value[1])
        if len(value) == 1:
            return (value[0], value[0])
    if type(value) is int:
        return (value, value)
    return (None, None)


def _dependency(dep):
    if isinstance(dep, str):
        return dep, (None, None)
    if isinstance(dep, (list, tuple)) and dep:
        if len(dep) == 2:
            return dep[0], _bounds(dep[1])
        if len(dep) >= 3:
            return dep[0], (dep[1], dep[2])
        return dep[0], (None, None)
    if not isinstance(dep, dict):
        return None

    name = dep.get("name", dep.get("package", dep.get("pkg")))
    if name is None and len(dep) == 1:
        name, spec = next(iter(dep.items()))
        return name, _bounds(spec)
    if name is None:
        return None

    spec = dep.get("range", dep.get("version_range", dep.get("versions")))
    if spec is None and "version" in dep:
        spec = dep["version"]
    if spec is not None:
        bounds = _bounds(spec)
    else:
        bounds = (
            dep.get("min", dep.get("min_version")),
            dep.get("max", dep.get("max_version")),
        )
    return name, bounds


def _allowed(version, constraints):
    return all(
        (low is None or version >= low) and (high is None or version <= high)
        for low, high in constraints
    )


def _acyclic(graph):
    visiting = set()
    visited = set()

    def visit(name):
        if name in visiting:
            return False
        if name in visited:
            return True
        visiting.add(name)
        for dependency in graph.get(name, []):
            if not visit(dependency):
                return False
        visiting.remove(name)
        visited.add(name)
        return True

    return all(visit(name) for name in graph)


def resolve(data):
    packages = data.get("packages", {})
    names = sorted(packages)
    roots = data.get("roots", {})
    pins = data.get("pins", {})
    blocked = data.get("blocked", {})
    features = data.get("features", []) or []

    constraints = {}
    for name, interval in roots.items():
        constraints.setdefault(name, []).append(_bounds(interval))

    best_key = None
    best_versions = None

    def search(assigned, required, graph):
        nonlocal best_key, best_versions

        for name, version in assigned.items():
            if not _allowed(version, required.get(name, [])):
                return
            if name in pins and version != pins[name]:
                return
            if version in blocked.get(name, []):
                return

        pending = [name for name in required if name not in assigned]
        if not pending:
            if not _acyclic(graph):
                return
            key = tuple(assigned.get(name, -1) for name in names)
            if best_key is None or key > best_key:
                best_key = key
                best_versions = dict(assigned)
            return

        name = min(pending)
        choices = [
            row for row in packages.get(name, [])
            if isinstance(row, dict)
            and type(row.get("version")) is int
            and _allowed(row["version"], required[name])
            and (name not in pins or row["version"] == pins[name])
            and row["version"] not in blocked.get(name, [])
        ]
        choices.sort(key=lambda row: row["version"], reverse=True)

        for row in choices:
            version = row["version"]
            next_assigned = dict(assigned)
            next_assigned[name] = version
            next_required = {pkg: list(bounds) for pkg, bounds in required.items()}
            next_graph = {pkg: list(deps) for pkg, deps in graph.items()}
            active_dependencies = []
            valid = True

            for dep in row.get("deps", []):
                if isinstance(dep, dict):
                    feature = dep.get("feature")
                    if feature not in (None, "") and feature not in features:
                        continue

                parsed = _dependency(dep)
                if parsed is None:
                    valid = False
                    break
                dep_name, bounds = parsed
                if not isinstance(dep_name, str):
                    valid = False
                    break

                active_dependencies.append(dep_name)
                next_required.setdefault(dep_name, []).append(bounds)
                if dep_name in next_assigned and not _allowed(
                    next_assigned[dep_name], next_required[dep_name]
                ):
                    valid = False
                    break

            if valid:
                next_graph[name] = active_dependencies
                search(next_assigned, next_required, next_graph)

    search({}, constraints, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
